const cancelled = $('Cancel Appointment in Database').first().json;

const hasError =
  Boolean($json.error) ||
  Boolean($json.errorMessage) ||
  $json.success === false;

return [
  {
    json: {
      ...cancelled,
      calendar_sync_status: hasError ? 'delete_failed' : 'deleted',
      calendar_sync_message: hasError
        ? 'نوبت در دیتابیس لغو شد، اما حذف رویداد تقویم نیاز به بررسی مجدد دارد.'
        : 'رویداد Google Calendar نیز حذف شد.',
    },
  },
];

return [
  {
    json: {
      ...$json,
      calendar_sync_status: 'not_required',
      calendar_sync_message: 'برای این نوبت شناسه رویداد تقویم ثبت نشده بود.',
    },
  },
];

return [
  {
    json: {
      success: false,
      result: 'invalid_request',
      message: 'اطلاعات درخواست ناقص یا نامعتبر است.',
      errors: $json.errors ?? [],
    },
  },
];

return [
  {
    json: {
      success: false,
      result: $json.result,
      message: $json.message,
      appointment_id: $json.appointment_id ?? null,
      patient_name: $json.patient_name ?? null,
      doctor_name: $json.doctor_name ?? null,
      service_name: $json.service_name ?? null,
      appointment_start: $json.appointment_start ?? null,
      current_status: $json.current_status ?? null,
    },
  },
];
